SELECT *
FROM urgency_record
WHERE member_id = #{memberId}
  AND tenant_id = #{tenantId}
ORDER BY create_time DESC
LIMIT #{limit}

SELECT COUNT(*)
FROM urgency_record
WHERE member_id = #{memberId}
  AND tenant_id = #{tenantId}
  AND DATE(create_time) = #{date}

SELECT COUNT(*)
FROM urgency_record
WHERE tenant_id = #{tenantId}
  AND DATE(create_time) = #{date}

SELECT COUNT(*)
FROM urgency_record
WHERE tenant_id = #{tenantId}
  AND create_time >= #{weekStart}
